INSERT INTO proc.bp_requirement (requirement_id,title,category,status,description,target_budget,currency,completeness_score,specifications,seed_context,created_at,updated_at) VALUES ('REQ-2041',$t$Managed cloud data platform$t$,$c$SaaS / IT$c$,'gathering',$d$Three overlapping data tools across BUs; spend fragmented and partly off-contract.$d$,480000,'GBP',64,$json${"criteria":["Consolidate to one platform","≥15% unit-rate reduction","99.95% SLA"]}$json$,$json${"title":"Managed cloud data platform","fromDemand":"DM-2041","commodity":"Technology & digital","category":"SaaS / IT","value":"£480,000","duration":"3 years + 2 optional","org":"Group · UK","status":"Clarifying","strength":64,"stage":"universal","problem":"Three overlapping data tools across BUs; spend fragmented and partly off-contract.","criteria":["Consolidate to one platform","≥15% unit-rate reduction","99.95% SLA"],"clarify":[{"role":"agent","area":"Scope boundaries","text":"Your demand is to consolidate three data tools onto one platform. Which capabilities are explicitly out of scope for the supplier — data migration, BI dashboards, or training?"},{"role":"user","text":"Migration is in scope; bespoke dashboards stay in-house, so out of scope. Training is in scope for admins only."},{"role":"agent","area":"Volume & scale","text":"How many users and what data volume must it support at peak, and what growth do you expect across the 3-year term?"}]}$json$,now(),now()) ON CONFLICT (requirement_id) DO NOTHING;
