INSERT INTO proc.bp_requirement (requirement_id,title,category,status,description,target_budget,currency,completeness_score,specifications,seed_context,created_at,updated_at) VALUES ('REQ-NEW',$t$Cloud data platform — annual renewal$t$,$c$IT · SaaS$c$,'gathering',$d$Renew our cloud data platform; spend fragmented across three tools and partly off-contract — consolidate onto one agreement with volume discounts and a 99.95% SLA.$d$,480000,'GBP',30,$json${"criteria":["Consolidate onto one platform","Committed volume discounts","99.95% SLA"]}$json$,$json${"title":"Cloud data platform — annual renewal","fromDemand":"DM-2041","commodity":"Technology & digital","category":"IT · SaaS","value":"£480,000","duration":"1 year","org":"Group · UK","status":"Clarifying","strength":30,"stage":"universal","problem":"Renew our cloud data platform; spend fragmented across three tools and partly off-contract — consolidate onto one agreement with volume discounts and a 99.95% SLA.","criteria":["Consolidate onto one platform","Committed volume discounts","99.95% SLA"],"clarify":[{"role":"agent","area":"Scope boundaries","text":"Thanks — I’ve carried the need, category, value and entity straight from your demand intake, so we won’t re-ask those. To shape a supplier-ready requirement: which capabilities are explicitly out of scope for the supplier — data migration, BI dashboards, or training?"}]}$json$,now(),now()) ON CONFLICT (requirement_id) DO NOTHING;
